    public static GUPFreeItemGroupId lastFreeItemGroupNum(RetailDiscountOfferId  _offerId)
    {
        return (select maxof(FreeItemGroup) from gUPFreeItemDiscountLine
			where gUPFreeItemDiscountLine.OfferId == _offerId).FreeItemGroup;
    }

public static GUPFreeItemDiscountLine find(RetailDiscountOfferId _offerId, boolean _forUpdate = false)
{
    GUPFreeItemDiscountLine freeItemDiscountLine;

    if (_offerId)
    {
        freeItemDiscountLine.selectForUpdate(_forUpdate);

        select firstonly freeItemDiscountLine
            where   freeItemDiscountLine.OfferId == _offerId;
    }

    return freeItemDiscountLine;
}

public void modifiedField(FieldId _fieldId)
{
    if (_fieldId == fieldNum(GUPFreeItemDiscountLine, FreeItemGroup) && this.FreeItemGroup != this.orig().FreeItemGroup)
    {
        if (GUPFreeItemLine::exists(this.OfferId, this.orig().FreeItemGroup))
        {
            this.updateFreeItemLine(this.FreeItemGroup, this.OfferId, this.orig().FreeItemGroup);
        }
    }

    super(_fieldId);
}

private void updateFreeItemLine(
    GUPFreeItemGroupId _newFreeItemGroup,
    RetailOfferId _offerId,
    GUPFreeItemGroupId _freeItemGroup)
{
    GUPFreeItemLine   freeItemLine;

    update_recordset freeItemLine setting 
        FreeItemGroup = _newFreeItemGroup
    where freeItemLine.FreeItemId == _offerId && freeItemLine.FreeItemGroup == _freeItemGroup;
}

public boolean validateDelete()
{
    boolean ret = super();

    if (GUPFreeItemLine::exists(this.OfferId, this.FreeItemGroup))
    {
        return checkFailed(strFmt("@GlobalUnifiedPricing:GUPFreeItemDiscountLineDeleteCheck"));
    }

    return ret;
}
